{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spf_mp_final AS SELECT t.*, CASE WHEN UPPER(status) IN (\'APPROVED\', \'ACCEPT\', \'PAYMENT_COMPLETED\') THEN \'Approved\' WHEN UPPER(status) IN (\'REJECTED\', \'REJECT\') THEN \'Rejected\' WHEN UPPER(status) IN ( \'AWAITING_SELLER_RESPONSE\', \'INVOICE_CREATED\', \'CUSTOMER REPLIED\', \'INVOICE_INITIATED\', \'OPEN\', \'UNATTENDED\', \'AWAITING_AGENT_RESPONSE\' ) THEN \'pending\' ELSE \'pending\' END AS final_status, CASE WHEN REJECTIONREASON ILIKE \'%same brand%\' OR REJECTIONREASON ILIKE \'%catalog%\' OR REJECTIONREASON ILIKE \'%not charged%\' OR REJECTIONREASON ILIKE \'%wrong size%\' OR REJECTIONREASON ILIKE \'%item_code%\' OR REJECTIONREASON ILIKE \'%claim_value%\' OR REJECTIONREASON ILIKE \'%cannot consider%\' OR REJECTIONREASON ILIKE \'%damage/used part%\' THEN \'Same brand equal price\' WHEN REJECTIONREASON ILIKE \'%out%tat%\' OR REJECTIONREASON ILIKE \'%tat breach%\' OR REJECTIONREASON ILIKE \'%beyond%tat%\' THEN \'Out tat\' WHEN REJECTIONREASON ILIKE \'%vms%\' THEN \'VMS\' WHEN REJECTIONREASON ILIKE \'%wfr%\' THEN \'WFR\' WHEN REJECTIONREASON ILIKE \'%video%\' OR REJECTIONREASON ILIKE \'%cctv%\' OR REJECTIONREASON ILIKE \'%360%\' OR REJECTIONREASON ILIKE \'%footage%\' OR REJECTIONREASON ILIKE \'%packing%\' OR REJECTIONREASON ILIKE \'%image%\' OR REJECTIONREASON ILIKE \'%six sided%\' OR REJECTIONREASON ILIKE \'%label%\' THEN \'video issue\' WHEN REJECTIONREASON ILIKE \'%tamper%\' OR REJECTIONREASON ILIKE \'%repack%\' OR REJECTIONREASON ILIKE \'%already opened%\' THEN \'tampered shipment\' WHEN REJECTIONREASON ILIKE \'%no response%\' THEN \'No response from seller\' WHEN REJECTIONREASON ILIKE \'%approved%\' OR REJECTIONREASON ILIKE \'%claim accepted%\' THEN \'Approved\' WHEN REJECTIONREASON ILIKE \'pending\' THEN \'pending\' WHEN REJECTIONREASON ILIKE \'%invalid%\' OR REJECTIONREASON ILIKE \'%not eligible%\' OR REJECTIONREASON ILIKE \'%duplicate%\' OR REJECTIONREASON ILIKE \'%insufficient%\' OR REJECTIONREASON ILIKE \'%wrong%\' OR REJECTIONREASON ILIKE \'%return delivered%\' OR REJECTIONREASON ILIKE \'%rto%\' THEN \'Invalid claim\' ELSE \'other\' END AS final_rejection_reason, CASE WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%FAKE%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DIFFERENT BRAND%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WRONG PRODUCT%\' THEN \'Fake\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%SHORT%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%MISSING%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%EMPTY BOX%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%PARTIAL%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%INCOMPLETE%\' THEN \'Short Qty\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DAMAGE%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%STAIN%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%DEFECTIVE%\' THEN \'damage\' WHEN REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WRONG RETURNS%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%WPR%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%SAME BRAND%\' OR REGEXP_REPLACE(UPPER(TRIM(ISSUECATEGORY)), \'[_/-]\', \' \') LIKE \'%STICK%\' THEN \'wpr\' ELSE \'other\' END AS final_issuecategory, TO_CHAR(parsed_date, \'Mon\') AS month, CASE WHEN TO_CHAR(parsed_date, \'Mon\') = \'Jan\' THEN 1 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Feb\' THEN 2 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Mar\' THEN 3 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Apr\' THEN 4 WHEN TO_CHAR(parsed_date, \'Mon\') = \'May\' THEN 5 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Jun\' THEN 6 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Jul\' THEN 7 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Aug\' THEN 8 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Sep\' THEN 9 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Oct\' THEN 10 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Nov\' THEN 11 WHEN TO_CHAR(parsed_date, \'Mon\') = \'Dec\' THEN 12 END AS month_order FROM ( SELECT *, COALESCE( TRY_TO_TIMESTAMP_TZ(CREATEDON), TRY_TO_TIMESTAMP(CREATEDON), TRY_TO_DATE(CREATEDON, \'DD-MON-YY\'), TRY_TO_DATE(CREATEDON, \'DD-MON-YYYY\'), TRY_TO_DATE(CREATEDON, \'DD-MM-YYYY\'), TRY_TO_DATE(CREATEDON, \'D-M-YYYY\'), TRY_TO_DATE(CREATEDON, \'YYYY-MM-DD\'), TRY_TO_DATE(CREATEDON, \'DD/MM/YYYY\'), TRY_TO_DATE(CREATEDON, \'MM/DD/YYYY\'), TRY_TO_DATE(CREATEDON) ) AS parsed_date FROM spf_mp ) t;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            